mapper.select:
SELECT g.id, g.product_id as productId, g.start_time as startTime, g.end_time as endTime, g.min_price as minPrice, g.max_price as maxPrice, g.minimum_number as minimumNumber, g.already_buy_number as alreadyBuyNumber, g.automatic_refund as automaticRefund, g.`status`, g.create_time as createTime, g.update_time as updateTime, s.ot_price as otPrice, s.price as price, s.vip_price as vipPrice, s.store_name as storeName, s.sales, s.image, s.unit_name as unitName FROM kx_group_shop AS g LEFT JOIN kx_store_product as s on s.id = g.product_id WHERE g.`status` = 1
and g.storage_id = #{storageId}
ORDER BY id DESC LIMIT #{offset}, #{limit}
